from __future__ import annotations

import base64
import os
import tempfile
import zlib
from pathlib import Path
from zipfile import ZipFile

REPORTS = (
    (
        Path("Shufan ZHANG 999018435/quantum_scattering_report.docx"),
        b"6. Part 6 - Complex scaling and resonance states",
        "",
    ),
    (
        Path("Yifeng CHEN 999016959/Quantum_Scattering_Project_Report.docx"),
        "Part 6 — Complex scaling and resonance states".encode("utf-8"),
        "",
    ),
)


def patch_report(path: Path, heading: bytes, payload: str) -> None:
    wrapped = zlib.decompress(base64.b64decode(payload))
    prefix = b"<part6>"
    suffix = b"</part6>"
    if not (wrapped.startswith(prefix) and wrapped.endswith(suffix)):
        raise RuntimeError(f"invalid embedded Part 6 payload for {path}")
    replacement = wrapped[len(prefix):-len(suffix)]
    if b"6.4 Comparison of resonance energies" not in replacement:
        raise RuntimeError(f"comparison section is missing from {path} payload")

    with ZipFile(path, "r") as source:
        infos = source.infolist()
        contents = {info.filename: source.read(info.filename) for info in infos}

    document = contents["word/document.xml"]
    heading_at = document.find(heading)
    if heading_at < 0:
        raise RuntimeError(f"Part 6 heading not found in {path}")
    start = max(document.rfind(b"<w:p>", 0, heading_at), document.rfind(b"<w:p ", 0, heading_at))
    end = document.rfind(b"<w:sectPr")
    if start < 0 or end <= start:
        raise RuntimeError(f"could not locate Part 6 XML range in {path}")

    updated = document[:start] + replacement + document[end:]
    if updated.count(b"6.4 Comparison of resonance energies") != 1:
        raise RuntimeError(f"Part 6 replacement validation failed for {path}")
    contents["word/document.xml"] = updated

    handle, temp_name = tempfile.mkstemp(prefix=path.stem + "_", suffix=".docx", dir=path.parent)
    os.close(handle)
    temporary = Path(temp_name)
    try:
        with ZipFile(temporary, "w") as destination:
            for info in infos:
                destination.writestr(info, contents[info.filename])
        with ZipFile(temporary, "r") as check:
            check_xml = check.read("word/document.xml")
        if check_xml.count(b"6.4 Comparison of resonance energies") != 1:
            raise RuntimeError(f"written report validation failed for {path}")
        temporary.replace(path)
    finally:
        temporary.unlink(missing_ok=True)


for report_path, report_heading, report_payload in REPORTS:
    patch_report(report_path, report_heading, report_payload)
    print(f"updated {report_path}")
